import { readFileSync, readdirSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import { woff2Codepoints } from './woff2Cmap'

/**
 * The subset is generated by hand (`tools/fonts/subset-cjk-font.py`) and committed, because the
 * Docker build runs on `node:24-alpine` and has no Python. That means nothing in CI regenerates it,
 * which in turn means a new Chinese label in a component could quietly land outside the subset and
 * render in the system face next to its neighbours. These tests are the thing that stops that:
 * they read the coverage out of the SHIPPED woff2's own cmap, not out of a list that claims to
 * describe it.
 */
const here = dirname(fileURLToPath(import.meta.url))
const repo = resolve(here, '../../../..')
const font = readFileSync(join(here, 'noto-sans-sc-subset.woff2'))
const covered = woff2Codepoints(font)

/**
 * The CJK blocks the subset declares a `unicode-range` for in styles.css, as numeric pairs rather
 * than a character class: written as a regexp the boundary codepoints are invisible glyphs in the
 * source, and this file would then report its own range markers as uncovered characters.
 */
const CJK_BLOCKS: [number, number][] = [
  [0x3000, 0x303f], // CJK punctuation
  [0x3400, 0x4dbf], // Extension A
  [0x4e00, 0x9fff], // Unified Ideographs
  [0xf900, 0xfaff], // Compatibility Ideographs
  [0xff00, 0xffef], // Fullwidth forms
]
const isCjk = (code: number) => CJK_BLOCKS.some(([lo, hi]) => code >= lo && code <= hi)
const EXT = ['.ts', '.tsx', '.css', '.html']

function sourceFiles(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name)
    if (entry.isDirectory()) sourceFiles(path, out)
    // Test files are excluded: they are not UI copy, and the sample characters below would
    // otherwise be found in this very file and prove nothing.
    else if (EXT.some((e) => entry.name.endsWith(e)) && !/\.test\.tsx?$/.test(entry.name))
      out.push(path)
  }
  return out
}

/** Every Chinese character the app itself writes, mapped to one file that writes it. */
function chromeVocabulary(): Map<string, string> {
  const found = new Map<string, string>()
  for (const root of [join(repo, 'apps/web/src'), join(repo, 'apps/api/src')]) {
    for (const file of sourceFiles(root)) {
      for (const char of readFileSync(file, 'utf8')) {
        if (isCjk(char.codePointAt(0)!) && !found.has(char))
          found.set(char, file.slice(repo.length + 1))
      }
    }
  }
  return found
}

describe('the self-hosted CJK subset', () => {
  it('covers every Chinese character the app writes', () => {
    const vocabulary = chromeVocabulary()
    // Guard the guard: if the scan ever finds nothing, the assertion below passes vacuously.
    expect(vocabulary.size).toBeGreaterThan(200)
    const missing = [...vocabulary].filter(([char]) => !covered.has(char.codePointAt(0)!))
    expect(
      missing.map(
        ([char, file]) =>
          `${char} (U+${char.codePointAt(0)!.toString(16).toUpperCase()}) first written in ${file}`,
      ),
    ).toEqual([])
  })

  it('covers what a user types, not only the UI chrome', () => {
    // These four han appear in real task titles and in NO label of the app (checked against the
    // scan above). A chrome-only subset (124.5 KiB) omits them, and because font fallback is per
    // glyph that would draw one task title in two faces at two weights. If this test fails, someone has narrowed the
    // character budget back to the UI's own vocabulary; see the note in styles.css.
    for (const char of '简舍练习') {
      expect(covered.has(char.codePointAt(0)!), `${char} is not in the subset`).toBe(true)
    }
    // GB2312 level 1 + 2 is 6,763 han; with Latin and CJK punctuation the budget is 6,879
    // codepoints. Well under that means the subset was rebuilt to a smaller budget.
    expect(covered.size).toBeGreaterThan(6500)
  })
})
